#include <bits/stdc++.h>
using namespace std;

int main(){
  vector<int> v(3);
  cin>>v[0]>>v[1]>>v[2];
  sort(v.begin(),v.end());

  if(v[0]!=v[1]&&v[1]!=v[2]){
    cout<<0<<endl;
  }
  else{
    //(a^b)でaとbの排他的論理和を表す
    cout<<(v[0]^v[1]^v[2])<<endl;
  }
}
